        let valid=true,socket:WebSocket|undefined,retry:ReturnType<typeof setTimeout>|undefined;const controller=new AbortController();const candidates:Record<string,number>={},rawResults:Record<string,Result>={};let statuses:ScopeStatuses={};let viewGeneration=0n,connection=0;
        const queue=new LatestScopeQueue<{raw:Result;connectionId:number}>(async ({raw,connectionId})=>{const scope=raw.resultScopeId || 'default';if(isScopeResultExpired(raw,statuses))return false;const attempt=(candidates[scope] || 0)+1;candidates[scope]=attempt;const panelPage=panelRef.current?.pages.find(p=>p.id===pageRef.current);const ready=await prepareResult(raw,controller.signal,pageImageSources(panelPage,scope));if(!valid || connectionId!==connection || attempt!==candidates[scope] || isScopeResultExpired(ready,statuses)){releaseResult(ready);return false;}ownedResults.current.add(ready);setResults(old=>{if(old[scope]){releaseResult(old[scope]);ownedResults.current.delete(old[scope]);}return {...old,[scope]:ready};});setLiveState(`同次结果 ${ready.resultKey}`);return true;});
